query {
  getProductData {
    id
    tags
    variants {
      title
      product {
        title
      }
      price
      compareAtPrice
    }
    discountPercent {
      value
    }
  }
}

export default function main(input) {
  // Extract products data from the input structure
  const productsData = input.getProductData || [];

  // Process each product to find its max discount
  const results = productsData.map((productData) => {
    const variants = productData.variants || [];
    const productId = productData.id;

    // Get product title from the first variant since it's not at the top level
    const productTitle = variants.length > 0 ? variants[0].product?.title : null;

    // Extract the custom discount_percent metafield value if it exists
    const discountMetafield = productData.discountPercent?.value ?? null;
    const currentDiscountPercentMetafield = discountMetafield != null ? parseFloat(discountMetafield) : null;


    let maxDiscountPercentage = 0;
    let maxDiscountVariantTitle = null;
    let maxDiscountPrice = null;
    let maxDiscountCompareAtPrice = null;

    // Iterate through variants to find max discount for this product
    variants.forEach(variant => {
      const price = parseFloat(variant.price);
      const compareAtPrice = parseFloat(variant.compareAtPrice);

      // Skip variants without valid prices or if compareAtPrice is null
      if (!price || !compareAtPrice || isNaN(compareAtPrice) || compareAtPrice <= price) {
        return;
      }

      // Calculate discount percentage
      const discountPercentage = ((compareAtPrice - price) / compareAtPrice) * 100;

      // Update max values if this discount is higher
      if (discountPercentage > maxDiscountPercentage) {
        maxDiscountPercentage = discountPercentage;
        maxDiscountVariantTitle = variant.title;
        maxDiscountPrice = price;
        maxDiscountCompareAtPrice = compareAtPrice;
      }
    });

    // Round to 2 decimal places
    maxDiscountPercentage = Math.round(maxDiscountPercentage * 100) / 100;

    return {
      productId,
      productTitle,
      maxDiscountPercentage,
      maxDiscountVariantTitle,
      maxDiscountPrice,
      maxDiscountCompareAtPrice,
      currentDiscountPercentMetafield,
    };
  });

  // Filter out any products that don't have valid data
  const validResults = results.filter(product => product.productId);

  return {
    products: validResults,
    count: validResults.length,
  };
}
